// RECURRING DETECTION — find the standing charges nobody is looking at.
//
// The highest-value capability in the finance set, and the reason is unglamorous: a forgotten
// subscription is found by NOBODY until something looks for it. It does not appear on a budget, it
// does not feel like a decision, and it renews on a schedule designed to be unremarkable.
//
// The output that matters is the ANNUALISED cost. "$14.99" prompts nothing; "$179.88 a year" prompts
// a cancellation. Same charge, and only one of those gets acted on.
//
// CONFIDENCE, NOT A VERDICT. A monthly bill whose amount moves — a utility, anything usage-based — is
// still recurring, and a detector demanding an identical amount would miss exactly the charges worth
// finding. So regularity and amount stability are scored separately and both are reported.
import { type Money, money, sum, scale } from "@/features/finance/lib/money";
import { type Txn, daysBetween, merchantKey } from "@/features/finance/lib/txn";

/** How often something recurs. `irregular` is a real answer, not a failure to classify. */
export type Cadence = "weekly" | "biweekly" | "monthly" | "quarterly" | "annual" | "irregular";

export interface Recurring {
  /** The merchant key the occurrences share — stable across the noise statements add. */
  readonly key: string;
  /** The most recent description, so a human recognises what it is. */
  readonly label: string;
  readonly account: string;
  readonly cadence: Cadence;
  /** Typical amount — the MEDIAN, not the mean: one annual true-up must not move the figure. */
  readonly typical: Money;
  /** What it costs over a year at this cadence. The number that prompts action. */
  readonly annualised: Money;
  readonly occurrences: number;
  readonly firstSeen: string;
  readonly lastSeen: string;
  /** 0-1. How evenly spaced the occurrences are; 1 is metronomic. */
  readonly regularity: number;
  /** 0-1. How stable the amount is; 1 is identical every time. */
  readonly amountStability: number;
  /** Nothing charged for noticeably longer than the cadence predicts. Either it was cancelled or it
   *  is about to hit, and those want different responses — so it is surfaced, not filtered away. */
  readonly lapsed: boolean;
}

const PER_YEAR: Record<Exclude<Cadence, "irregular">, number> = {
  weekly: 52,
  biweekly: 26,
  monthly: 12,
  quarterly: 4,
  annual: 1,
};

/** Interval in days each cadence implies, and how far a gap may stray and still count. */
const CADENCE_DAYS: [Exclude<Cadence, "irregular">, number, number][] = [
  ["weekly", 7, 2],
  ["biweekly", 14, 3],
  ["monthly", 30, 5],
  ["quarterly", 91, 12],
  ["annual", 365, 35],
];

const median = (xs: number[]): number => {
  const s = [...xs].sort((a, b) => a - b);
  const m = Math.floor(s.length / 2);
  return s.length % 2 ? s[m] : Math.round((s[m - 1] + s[m]) / 2);
};

/** The cadence whose expected interval the observed gaps sit closest to. */
function classify(gaps: number[]): { cadence: Cadence; regularity: number } {
  if (!gaps.length) return { cadence: "irregular", regularity: 0 };
  const typical = median(gaps);
  const match = CADENCE_DAYS.find(([, days, tol]) => Math.abs(typical - days) <= tol);
  if (!match) return { cadence: "irregular", regularity: 0 };
  const [cadence, days] = match;
  // Regularity measures how tightly the gaps CLUSTER on the expected interval, not merely that the
  // median landed near it: twelve charges at 30 days and twelve alternating 5/55 share a median.
  const drift = gaps.reduce((a, g) => a + Math.abs(g - days), 0) / gaps.length;
  return { cadence, regularity: Math.max(0, 1 - drift / days) };
}

export interface DetectOptions {
  /** Fewest occurrences before something counts as recurring. TWO is deliberate — an annual charge
   *  cannot show three inside a year of statements, and demanding three would hide precisely the
   *  once-a-year renewals that are easiest to forget and most expensive to keep. */
  readonly minOccurrences?: number;
  /** Ignore inbound money; income has its own capability and its own questions. */
  readonly outflowsOnly?: boolean;
  /** `YYYY-MM-DD` — what "now" is, for the lapsed check. Passed IN, never read from a clock, so the
   *  same data gives the same answer on a re-run and a test is not a moving target. */
  readonly asOf: string;
}

/** Group by merchant AND account, then judge each group's rhythm. */
export function detectRecurring(txns: readonly Txn[], opts: DetectOptions): Recurring[] {
  const { minOccurrences = 2, outflowsOnly = true, asOf } = opts;

  const groups = new Map<string, Txn[]>();
  for (const t of txns) {
    if (outflowsOnly && t.amount.minor >= 0) continue;
    const key = merchantKey(t.description);
    if (!key) continue;
    // Keyed on the ACCOUNT too: one subscription billed to two cards is two standing charges, and
    // merging them would halve the count while doubling the apparent amount.
    const id = `${t.account}�${key}`;
    const bucket = groups.get(id);
    if (bucket) bucket.push(t);
    else groups.set(id, [t]);
  }

  const out: Recurring[] = [];
  for (const [id, rows] of groups) {
    if (rows.length < minOccurrences) continue;
    const sorted = [...rows].sort((a, b) => a.date.localeCompare(b.date));
    const gaps: number[] = [];
    for (let i = 1; i < sorted.length; i++) gaps.push(daysBetween(sorted[i - 1].date, sorted[i].date));
    const { cadence, regularity } = classify(gaps);
    if (cadence === "irregular") continue;

    const amounts = sorted.map((t) => Math.abs(t.amount.minor));
    const typicalMinor = median(amounts);
    const spread = amounts.reduce((a, v) => a + Math.abs(v - typicalMinor), 0) / amounts.length;
    const amountStability = typicalMinor === 0 ? 1 : Math.max(0, 1 - spread / typicalMinor);

    const last = sorted[sorted.length - 1];
    const typical = money(typicalMinor, last.amount.currency);
    const [, expected, tol] = CADENCE_DAYS.find(([c]) => c === cadence)!;

    out.push({
      key: id.split("�")[1],
      label: last.description,
      account: last.account,
      cadence,
      typical,
      annualised: scale(typical, PER_YEAR[cadence as Exclude<Cadence, "irregular">]),
      occurrences: sorted.length,
      firstSeen: sorted[0].date,
      lastSeen: last.date,
      regularity: Math.round(regularity * 100) / 100,
      amountStability: Math.round(amountStability * 100) / 100,
      lapsed: daysBetween(last.date, asOf) > expected + tol,
    });
  }
  // Biggest annual cost first — the order a reader wants, because it is the order to act in.
  return out.sort((a, b) => b.annualised.minor - a.annualised.minor);
}

/** What every LIVE recurring charge costs in a year, together. Usually the number that lands. */
export function totalAnnualised(rs: readonly Recurring[], currency: string): Money {
  return sum(
    rs.filter((r) => !r.lapsed).map((r) => r.annualised),
    currency,
  );
}

