import { describe, it, expect } from "vitest";
import { fromMajor, type Money } from "@/features/finance/lib/money";
import { detectRecurring, totalAnnualised } from "@/features/finance/lib/recurring";
import type { Txn } from "@/features/finance/lib/txn";

// EVERY FIXTURE IS SYNTHETIC — invented merchants, invented amounts. No real statement belongs here.

const usd = (major: number): Money => fromMajor(major, "USD");
const t = (date: string, description: string, major: number, account = "card"): Txn => ({
  date,
  description,
  amount: usd(-Math.abs(major)),
  account,
});

/** Twelve monthly charges, with the noise a statement actually adds to each line. */
const monthly = (merchant: string, major: number, account = "card"): Txn[] =>
  Array.from({ length: 12 }, (_, i) =>
    t(`2026-${String(i + 1).padStart(2, "0")}-14`, `${merchant} *RECURRING 1234${i}`, major, account),
  );

describe("detectRecurring — the rhythm", () => {
  it("finds a monthly charge through the noise the statement adds", () => {
    // A recurring charge rarely writes itself identically twice. Matching raw descriptions would find
    // nothing at all — the failure mode that makes a detector look like it works.
    const r = detectRecurring(monthly("STREAMSERVICE", 14.99), { asOf: "2026-12-20" });
    expect(r).toHaveLength(1);
    expect(r[0].cadence).toBe("monthly");
    expect(r[0].occurrences).toBe(12);
    expect(r[0].regularity).toBeGreaterThan(0.9);
  });

  it("ANNUALISES, because that is the number that prompts a cancellation", () => {
    const [r] = detectRecurring(monthly("STREAMSERVICE", 14.99), { asOf: "2026-12-20" });
    expect(r.typical.minor).toBe(1499);
    expect(r.annualised.minor).toBe(1499 * 12);
  });

  it("keeps a bill whose AMOUNT moves — a utility is still recurring", () => {
    // Demanding an identical amount would miss exactly the charges worth finding.
    const varying = monthly("CITY POWER", 0).map((x, i) => ({ ...x, amount: usd(-(80 + i * 3)) }));
    const [r] = detectRecurring(varying, { asOf: "2026-12-20" });
    expect(r.cadence).toBe("monthly");
    expect(r.amountStability).toBeLessThan(1);
    expect(r.regularity).toBeGreaterThan(0.9);
  });

  it("does NOT call an irregular spend recurring", () => {
    // The false positive is what kills the feature: flag someone's coffee habit as a subscription and
    // they stop reading the report.
    const coffee = ["2026-01-03", "2026-01-05", "2026-02-19", "2026-02-20", "2026-05-01"].map((d) =>
      t(d, "COFFEE BAR", 4.5),
    );
    expect(detectRecurring(coffee, { asOf: "2026-06-01" })).toEqual([]);
  });

  it("distinguishes cadences rather than calling everything monthly", () => {
    const weekly = Array.from({ length: 8 }, (_, i) =>
      t(`2026-03-${String(2 + i * 7).padStart(2, "0")}`, "GYM CLASS", 22),
    );
    expect(detectRecurring(weekly, { asOf: "2026-04-25" })[0].cadence).toBe("weekly");
  });
});

describe("detectRecurring — the once-a-year charge", () => {
  it("finds an ANNUAL renewal from two occurrences", () => {
    // Two is deliberate. An annual charge cannot show three inside a year of statements, and
    // demanding three would hide precisely the renewals that are easiest to forget.
    const annual = [t("2025-04-02", "DOMAIN RENEWAL", 240), t("2026-04-03", "DOMAIN RENEWAL", 240)];
    const [r] = detectRecurring(annual, { asOf: "2026-05-01" });
    expect(r.cadence).toBe("annual");
    expect(r.annualised.minor).toBe(24000);
  });
});

describe("detectRecurring — what it separates", () => {
  it("keeps the same subscription on TWO accounts apart", () => {
    // One subscription billed to two cards is two standing charges. Merging them would halve the
    // count and double the apparent amount — wrong in both directions at once.
    const both = [...monthly("SAME SERVICE", 9.99, "card-a"), ...monthly("SAME SERVICE", 9.99, "card-b")];
    const r = detectRecurring(both, { asOf: "2026-12-20" });
    expect(r).toHaveLength(2);
    expect(r.map((x) => x.account).sort()).toEqual(["card-a", "card-b"]);
  });

  it("ignores INCOME by default — it has its own questions", () => {
    const paydays = Array.from({ length: 12 }, (_, i) => ({
      ...t(`2026-${String(i + 1).padStart(2, "0")}-01`, "EMPLOYER PAYROLL", 0),
      amount: usd(2500),
    }));
    expect(detectRecurring(paydays, { asOf: "2026-12-20" })).toEqual([]);
    expect(detectRecurring(paydays, { asOf: "2026-12-20", outflowsOnly: false })).toHaveLength(1);
  });
});

describe("detectRecurring — lapsed", () => {
  it("flags a charge that has stopped, rather than dropping it", () => {
    // Cancelled, or about to hit? Those want different responses, so it is surfaced either way.
    const stopped = monthly("OLD SERVICE", 30).slice(0, 6); // last is 2026-06-14
    const [r] = detectRecurring(stopped, { asOf: "2026-10-01" });
    expect(r.lapsed).toBe(true);
  });

  it("does not count a lapsed charge in the annual total", () => {
    const live = monthly("LIVE ONE", 10);
    const dead = monthly("DEAD ONE", 50, "other").slice(0, 4);
    const rs = detectRecurring([...live, ...dead], { asOf: "2026-12-20" });
    expect(rs.find((r) => r.key.includes("dead"))?.lapsed).toBe(true);
    // Only the live one is money still going out.
    expect(totalAnnualised(rs, "USD").minor).toBe(1000 * 12);
  });
});

describe("detectRecurring — ordering", () => {
  it("puts the biggest ANNUAL cost first, which is the order to act in", () => {
    // Not the biggest per-charge: a $60 quarterly costs less a year than a $30 monthly, and a reader
    // ranking by the sticker price would cancel the wrong one.
    const monthlySmall = monthly("SMALL MONTHLY", 30);
    const quarterly = ["2026-01-10", "2026-04-11", "2026-07-10", "2026-10-11"].map((d) =>
      t(d, "BIG QUARTERLY", 60, "other"),
    );
    const rs = detectRecurring([...monthlySmall, ...quarterly], { asOf: "2026-11-01" });
    expect(rs[0].annualised.minor).toBe(3000 * 12);
    expect(rs[0].annualised.minor).toBeGreaterThan(rs[1].annualised.minor);
  });

  it("is deterministic — the same input twice gives the same answer", () => {
    const input = [...monthly("A SERVICE", 12), ...monthly("B SERVICE", 8, "other")];
    const a = JSON.stringify(detectRecurring(input, { asOf: "2026-12-20" }));
    const b = JSON.stringify(detectRecurring([...input].reverse(), { asOf: "2026-12-20" }));
    expect(a).toBe(b);
  });
});
